function _wrapKindNameOf(entry: unknown): string | undefined {
	if (!entry || typeof entry !== 'object') return undefined;
	const raw: unknown = _kindOf(entry as _UntypedNode);
	if (raw === undefined) return undefined;
	if (typeof raw === 'number') return KIND_NAMES.get(raw as never) ?? String(raw);
	return typeof raw === 'string' ? raw : undefined;
}

function _matchesAllowedWrapKind(kind: string, allowedKinds: readonly string[]): boolean {
	if (allowedKinds.includes(kind)) return true;
	const stripped = kind.startsWith('_') ? kind.slice(1) : undefined;
	if (stripped && allowedKinds.includes(stripped)) return true;
	for (const allowed of allowedKinds) {
		const members =
			SUPERTYPE_MEMBERS[allowed] ?? SUPERTYPE_MEMBERS[allowed.startsWith('_') ? allowed.slice(1) : allowed];
		if (members?.has(kind)) return true;
		if (stripped !== undefined && members?.has(stripped)) return true;
		const allowedStripped = allowed.startsWith('_') ? allowed.slice(1) : allowed;
		if (allowedStripped === kind || (stripped !== undefined && allowedStripped === stripped)) return true;
	}
	return false;
}

// Kind-keyed child probe: the grammar-agnostic reader stores an
// unlabeled named child under `_<childKind>` (read_untyped_node.rs kind-named
// slots). A VISIBLE supertype occurrence (an enrich-minted alias like
// `alias($._expression_except_range, $.expression_group1)`) therefore
// carries its single member child as a kind-keyed property, NOT in
// `$other` — probe those keys before falling back to the `$other` scan.
function _firstKindKeyedWrapChild(data: object, allowedKinds: readonly string[]): unknown {
	for (const key of Object.keys(data)) {
		if (key.charCodeAt(0) !== 95 /* `_` */) continue;
		const stripped = key.slice(1);
		if (!_matchesAllowedWrapKind(stripped, allowedKinds) && !_matchesAllowedWrapKind(key, allowedKinds)) continue;
		const value = (data as Record<string, unknown>)[key];
		if (value !== undefined) return value;
	}
	return undefined;
}

function _filterWrapChildrenByKind<T>(value: readonly T[], allowedKinds: readonly string[]): readonly T[];
function _filterWrapChildrenByKind<T>(
	value: T | readonly T[] | undefined,
	allowedKinds: readonly string[]
): T | readonly T[] | undefined;
function _filterWrapChildrenByKind<T>(
	value: T | readonly T[] | undefined,
	allowedKinds: readonly string[]
): T | readonly T[] | undefined {
	if (value == null) return undefined;
	if (!Array.isArray(value)) {
		const kind = _wrapKindNameOf(value);
		if (kind === undefined) return value;
		return _matchesAllowedWrapKind(kind, allowedKinds) ? value : undefined;
	}
	const entries = value;
	return entries.filter((entry) => {
		// Text-collapsed leaf elements (e.g. identifiers rendered as their
		// $text string) survive the legacy readUntypedNode walker but carry no $type
		// to classify. Keep them — the field tag already selected the slot\u2019s
		// content. Numeric separator kind-ids stay dropped (the template\u2019s
		// join re-adds separators).
		if (typeof entry === 'string') return true;
		const kind = _wrapKindNameOf(entry);
		if (kind === undefined) return false;
		return _matchesAllowedWrapKind(kind, allowedKinds);
	});
}

// A wire delimiter is a field-tagged separator token: either its bare
// numeric kind id (text-collapsed contexts) or an anonymous node stub
// `{ $type: <id>, $named: false }` (node-stub contexts).
type _WireDelimiter = number | { readonly $type: number; readonly $named: false };
function _isWireDelimiter(e: unknown, separatorKindIds: readonly number[]): e is _WireDelimiter {
	if (typeof e === 'number') return separatorKindIds.includes(e);
	if (typeof e === 'object' && e !== null) {
		const stub = e as { $type?: unknown; $named?: unknown };
		return stub.$named === false && typeof stub.$type === 'number' && separatorKindIds.includes(stub.$type);
	}
	return false;
}

function _dropOrderEntry(order: string[] | undefined, slot: string, occurrence: number): void {
	if (order === undefined) return;
	let seen = 0;
	const at = order.findIndex((name) => name === slot && seen++ === occurrence);
	if (at >= 0) order.splice(at, 1);
}

// A delimiter the parser field-tagged into a slot is punctuation the
// render body writes itself, so it is dropped rather than stored, and
// its entry leaves the node's `$slotOrder` draft with it.
// Assumes T itself is never an array type — slot elements are node unions.
function dropWireDelimiters<T>(
	value: T | readonly (T | _WireDelimiter)[] | undefined,
	separatorKindIds: readonly number[],
	order: string[] | undefined,
	slot: string
): T | readonly T[] | undefined {
	const isSlotList = (v: T | readonly (T | _WireDelimiter)[]): v is readonly (T | _WireDelimiter)[] => Array.isArray(v);
	if (value == null) return undefined;
	if (!isSlotList(value)) {
		if (!_isWireDelimiter(value, separatorKindIds)) return value;
		_dropOrderEntry(order, slot, 0);
		return undefined;
	}
	let kept = 0;
	return value.filter((e): e is T => {
		if (!_isWireDelimiter(e, separatorKindIds)) return (kept++, true);
		_dropOrderEntry(order, slot, kept);
		return false;
	});
}

export function wrapModule(data: T.Module, tree: TreeHandle): T.Module.Parsed {
	data = modelSlots(data, ['_statements']);
	const handle = currentHandle();
	const node = {
		...data,
		$type: TSKindId.Module as const,
		_statements: storeExpanded(
			normalizeRepeatedWrapSlot(data._statements, false, 'statements', {
				tree,
				nodeType: data.$type,
				slotName: 'statements',
				span: (data as _UntypedNode).$span
			}),
			tree
		),

		statements() {
			return hydrateSlots<T.Statement>(this, '_statements', tree);
		},
		$with: {
			statements: (...v: NonNullable<T.Module['_statements']>[number][]) =>
				rebuilt(node, handle, () => wrapModule({ ...$edited(data), _statements: restItems('statements', v) }, tree))
		},
		$render: () => renderText(handle, node),
		$trivia: {
			leading: (...items: unknown[]) => triviaSide(node, handle, 'leading', items),
			trailing: (...items: unknown[]) => triviaSide(node, handle, 'trailing', items),
			inner: (...items: unknown[]) => triviaInner(node, handle, items)
		},
		$query: handle && treeHandleOf(data) !== undefined ? () => queryOf(handle, node) : undefined,
		$engine: handle && (() => handle.current)
	};
	return node as unknown as T.Module.Parsed;
}

export function wrapStatement(
	data: T.Statement & { readonly $other?: T.Statement | readonly T.Statement[] },
	tree: TreeHandle
): T.Statement.Parsed {
	if (typeof data === 'number') return data as unknown as T.Statement.Parsed;
	const node = modelSlots(data, [
		'__simple_statements',
		'_simple_statements',
		'__compound_statement',
		'_compound_statement',
		'_if_statement',
		'_for_statement',
		'_while_statement',
		'_try_statement',
		'_with_statement',
		'_function_definition',
		'_class_definition',
		'_decorated_definition',
		'_match_statement'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'_simple_statements',
		'simple_statements',
		'_compound_statement',
		'compound_statement',
		'if_statement',
		'for_statement',
		'while_statement',
		'try_statement',
		'with_statement',
		'function_definition',
		'class_definition',
		'decorated_definition',
		'match_statement'
	]) as T.Statement | readonly T.Statement[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'_simple_statements',
			'simple_statements',
			'_compound_statement',
			'compound_statement',
			'if_statement',
			'for_statement',
			'while_statement',
			'try_statement',
			'with_statement',
			'function_definition',
			'class_definition',
			'decorated_definition',
			'match_statement'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.Statement>(node as T.Statement, tree) as unknown as T.Statement.Parsed;
	}
	return hydrateChild<T.Statement>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

export function wrapSimpleStatements(data: T.SimpleStatements, tree: TreeHandle): T.SimpleStatements.Parsed {
	data = modelSlots(data, ['_elements']);
	const handle = currentHandle();
	const _elements = storeExpanded(
		normalizeSingularWrapSlot(data._elements, 'elements', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'elements',
			span: (data as _UntypedNode).$span
		}),
		tree
	);
	const listView = ownerView(_elements, '_item', (list) => hydrateChild(list, tree));
	const node = {
		...data,
		$type: TSKindId.SimpleStatements as const,
		_elements,

		elements() {
			return hydrateSlot<T.SimpleStatementsElements>(this, '_elements', tree);
		},
		$with: {
			elements: (...args: unknown[]) =>
				rebuilt(node, handle, () =>
					listSlotWith(
						args,
						{
							kind: TSKindId.SimpleStatementsElements as const,
							optional: false,
							make: RAW.buildSimpleStatementsElements
						},
						(v: NonNullable<T.SimpleStatements['_elements']>) =>
							wrapSimpleStatements({ ...$edited(data), _elements: v }, tree)
					)
				)
		},
		length: listView.stored?.length,
		[LIST_ITEMS]: undefined,
		[LIST_READ]: () => listItems(ownerElements(node.elements(), 'items'), undefined),
		...LIST_METHODS,
		[Symbol.iterator]: listIterator,
		[Symbol.isConcatSpreadable]: true,
		[Symbol.unscopables]: Array.prototype[Symbol.unscopables],
		delimiter: listOption(listView.list, 'delimiter', undefined),
		$render: () => renderText(handle, node),
		$trivia: {
			leading: (...items: unknown[]) => triviaSide(node, handle, 'leading', items),
			trailing: (...items: unknown[]) => triviaSide(node, handle, 'trailing', items)
		},
		$query: handle && treeHandleOf(data) !== undefined ? () => queryOf(handle, node) : undefined,
		$engine: handle && (() => handle.current)
	};
	defineListIndices(node, listView.stored?.length ?? 0);
	return node as unknown as T.SimpleStatements.Parsed;
}

