export function wrapParameter(
	data: T.Parameter & { readonly $other?: T.Parameter | readonly T.Parameter[] },
	tree: TreeHandle
): T.Parameter.Parsed {
	if (typeof data === 'number') return data as unknown as T.Parameter.Parsed;
	const node = modelSlots(data, [
		'_identifier',
		'_typed_parameter',
		'_default_parameter',
		'_typed_default_parameter',
		'_list_splat_pattern',
		'_tuple_pattern',
		'_keyword_separator',
		'_positional_separator',
		'_dictionary_splat_pattern'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'identifier',
		'typed_parameter',
		'default_parameter',
		'typed_default_parameter',
		'list_splat_pattern',
		'tuple_pattern',
		'keyword_separator',
		'positional_separator',
		'dictionary_splat_pattern'
	]) as T.Parameter | readonly T.Parameter[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'identifier',
			'typed_parameter',
			'default_parameter',
			'typed_default_parameter',
			'list_splat_pattern',
			'tuple_pattern',
			'keyword_separator',
			'positional_separator',
			'dictionary_splat_pattern'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.Parameter>(node as T.Parameter, tree) as unknown as T.Parameter.Parsed;
	}
	return hydrateChild<T.Parameter>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

