export function wrapAssignment(
	data: T.Assignment & { readonly $other?: T.Assignment | readonly T.Assignment[] },
	tree: TreeHandle
): T.Assignment.Parsed {
	if (typeof data === 'number') return data as unknown as T.Assignment.Parsed;
	const node = modelSlots(data, ['_assignment_eq', '_assignment_type', '_assignment_typed']);
	const kindKeyed = _firstKindKeyedWrapChild(node, ['assignment_eq', 'assignment_type', 'assignment_typed']) as
		| T.Assignment
		| readonly T.Assignment[]
		| undefined;
	const filtered =
		kindKeyed ?? _filterWrapChildrenByKind(node.$other, ['assignment_eq', 'assignment_type', 'assignment_typed']);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.Assignment>(node as T.Assignment, tree) as unknown as T.Assignment.Parsed;
	}
	return hydrateChild<T.Assignment>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

