export function wrapIntegerDecimal(
	data: T.IntegerDecimal & { readonly $other?: T.IntegerDecimal | readonly T.IntegerDecimal[] },
	tree: TreeHandle
): T.IntegerDecimal.Parsed {
	if (typeof data === 'number') return data as unknown as T.IntegerDecimal.Parsed;
	const node = modelSlots(data, ['_integer_decimal_long', '_integer_decimal_imaginary', '_integer_decimal_plain']);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'integer_decimal_long',
		'integer_decimal_imaginary',
		'integer_decimal_plain'
	]) as T.IntegerDecimal | readonly T.IntegerDecimal[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'integer_decimal_long',
			'integer_decimal_imaginary',
			'integer_decimal_plain'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.IntegerDecimal>(node as T.IntegerDecimal, tree) as unknown as T.IntegerDecimal.Parsed;
	}
	return hydrateChild<T.IntegerDecimal>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

